#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

# Current-version assertions are intentionally advanced with each Installer release.
for path in ROOT.joinpath("tests").glob("test*.py"):
    text = path.read_text(encoding="utf-8")
    updated = text.replace('INSTALLER_VERSION == "2.1.23"', 'INSTALLER_VERSION == "2.1.24"')
    if updated != text:
        path.write_text(updated, encoding="utf-8", newline="\n")

regression = ROOT / "tests/test_v2_1_24_rate_limit_safe_release.py"
regression.write_text('''from __future__ import annotations\n\nimport importlib.util\nimport sys\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nROOT = Path(__file__).resolve().parents[1]\nAPP = ROOT / "switch_vision_installer" / "app"\n\n\ndef load_module(name: str, path: Path):\n    spec = importlib.util.spec_from_file_location(name, path)\n    assert spec and spec.loader\n    module = importlib.util.module_from_spec(spec)\n    sys.modules[name] = module\n    spec.loader.exec_module(module)\n    return module\n\n\n# test_component_manager.py deliberately installs a fake module named "installer"\n# for its isolated regression. Replace that stub here with the actual v2.1.24 source.\ninstaller = load_module("installer_v2124_actual", APP / "installer.py")\nsys.modules["installer"] = installer\nrepository_setup = load_module("repository_setup_v2124_actual", APP / "repository_setup.py")\nsys.modules["repository_setup"] = repository_setup\ncomponent_manager = load_module("component_manager_v2124_actual", APP / "component_manager.py")\n\n\nclass FakeRedirectResponse:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, exc_type, exc, tb):\n        return False\n\n    def geturl(self):\n        return "https://github.com/zemerdon/switch-vision-releases/releases/tag/2.4.3"\n\n\nclass InstallerRateLimitSafeReleaseTests(unittest.TestCase):\n    def test_official_version_uses_releases_redirect_not_rest_api(self):\n        seen = []\n\n        def fake_urlopen(request, timeout=0):\n            seen.append((request.full_url, request.get_method()))\n            return FakeRedirectResponse()\n\n        with patch.object(installer.urllib.request, "urlopen", side_effect=fake_urlopen):\n            self.assertEqual(installer.official_latest_release_version(), "2.4.3")\n\n        self.assertEqual(seen, [(installer.OFFICIAL_RELEASE_LATEST_URL, "HEAD")])\n        self.assertFalse(any("api.github.com" in url for url, _ in seen))\n\n    def test_official_metadata_is_deterministic_and_checksum_backed(self):\n        with patch.object(installer, "official_latest_release_version", return_value="2.4.3"), \\\n             patch.object(installer, "_official_release_notes", return_value="notes"):\n            release = installer.official_latest_release()\n\n        self.assertEqual(release["asset_name"], "switch-vision-2.4.3.zip")\n        self.assertEqual(\n            release["asset_url"],\n            "https://github.com/zemerdon/switch-vision-releases/releases/download/2.4.3/switch-vision-2.4.3.zip",\n        )\n        self.assertEqual(release["checksum_asset_name"], "switch-vision-2.4.3.zip.sha256")\n        self.assertTrue(release["checksum_asset_url"].endswith("/switch-vision-2.4.3.zip.sha256"))\n        self.assertIsNone(release["asset_digest"])\n\n    def test_official_latest_release_does_not_call_request_json(self):\n        options = {\n            "release_api_url": installer.OFFICIAL_RELEASE_API_URL,\n            "allow_custom_release_source": False,\n            "release_asset_pattern": "switch-vision-*.zip",\n            "allow_prerelease": False,\n        }\n        with patch.object(installer, "load_options", return_value=options), \\\n             patch.object(installer, "official_latest_release", return_value={"version": "2.4.3"}) as official, \\\n             patch.object(installer, "request_json", side_effect=AssertionError("REST API must not be used")):\n            self.assertEqual(installer.latest_release()["version"], "2.4.3")\n            official.assert_called_once_with()\n\n    def test_component_manager_core_status_uses_same_non_api_resolver(self):\n        component_manager.clear_cache()\n        core = next(spec for spec in component_manager.COMPONENTS if spec.component_id == "core")\n        with patch.object(installer, "official_latest_release_version", return_value="2.4.3") as latest, \\\n             patch.object(component_manager, "_github_request", side_effect=AssertionError("REST API must not be used")):\n            self.assertEqual(component_manager._remote_version(core), "2.4.3")\n            latest.assert_called_once_with()\n\n    def test_component_manager_core_changelog_is_raw_repository_text(self):\n        core = next(spec for spec in component_manager.COMPONENTS if spec.component_id == "core")\n        with patch.object(component_manager, "resolve_repository", return_value="switch-vision-releases"), \\\n             patch.object(component_manager, "_raw_text", return_value="# Changelog\\n") as raw, \\\n             patch.object(component_manager, "_component_status", return_value={"latest_version": "2.4.3", "installed_version": "2.4.2"}), \\\n             patch.object(component_manager, "_github_request", side_effect=AssertionError("REST API must not be used")):\n            payload = component_manager.component_changelog(core.component_id)\n        self.assertEqual(payload["changelog"], "# Changelog\\n")\n        raw.assert_called_once_with("switch-vision-releases", "CHANGELOG.md")\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8", newline="\n")

print("Updated Installer v2.1.24 regression harness")
